#include "item_stats.hpp"
#include <algorithm>
namespace mu::ui {
unsigned maximum_durability(const mu::client::Item& item,const ItemAttribute& a){unsigned n=item.index/512==5?a.magicDurability:a.baseDurability;for(unsigned i=0;i<item.level&&item.index<13*512+51;i++)n+=i>=14?8:i>=13?7:i>=12?6:i>=11?5:i>=10?4:i>=9?3:i>=4?2:1;if((item.setOption&3)==1||(item.setOption&3)==2)n+=20;else if(item.excellent&&!(item.index>=12*512+3&&item.index<=12*512+6)&&item.index!=19&&item.index!=4*512+18&&item.index!=5*512+10&&item.index!=13*512+30&&!(item.index>=12*512+36&&item.index<=12*512+43)&&item.index!=2*512+13&&!(item.index>=12*512+49&&item.index<=12*512+50))n+=15;return std::min(n,255u);}
std::array<double,4> item_background(const mu::client::Item& item,const ItemAttribute& a){auto normal=std::array<double,4>{.3,.5,.5,.6};unsigned group=item.index/512,type=item.index%512;bool endurance=group<12||(group==12&&(type<=6||(type>=36&&type<=43)||type==49||type==50||(type>=130&&type<=135)))||(group==13&&(type<=5||type==8||type==9||type==10||type==12||type==13||type==20||(type>=21&&type<=28)||type==30||type==37||(type>=38&&type<=42)||type==64||type==65||type==76||type==80||type==107||type==122||type==123));if(!endurance||(group==13&&type==20&&(item.level==1||item.level==2)))return normal;unsigned max=maximum_durability(item,a);if(!item.durability)return {1,0,0,.4};if(max&&item.durability<=max*.2)return {1,.33,0,.4};if(max&&item.durability<=max*.3)return {1,.66,0,.4};if(max&&item.durability<=max*.5)return {1,1,0,.4};return normal;}
ItemStats equipment_stats(const mu::client::Item& item,const ItemAttribute& a){ItemStats s;unsigned group=item.index/512,type=item.index%512;s.supported=group<=11;const unsigned level=item.level,extra=level>=10?(level-9)*(level-8)/2:0,upgrade=level*3+extra;const bool ancient=((item.setOption&3)==1||(item.setOption&3)==2)&&(((item.setOption>>2)&3)==1||((item.setOption>>2)&3)==2);unsigned effective=a.baseLevel+((item.excellent||ancient)?25:0);for(unsigned n=0;n<5;n++){unsigned mul=n==2?4:3,steps=level*3;if(n==2&&group==5&&a.wearSlot==1){mul=3;steps=level;}s.requirements[n]=a.requirements[n]?20+a.requirements[n]*(effective+steps)*mul/100:0;}s.requirements[5]=a.requirements[5];if(group>=12&&a.requirements[5]){bool fixed=group==12&&(((type>=7&&type<=24)&&type!=15)||(type>=36&&type<=40)||type==43||type==50||(type>=44&&type<=48)||(type>=130&&type<=135)||type==266||type==267);if(!fixed)s.requirements[5]+=level*((group==12&&((type>=3&&type<=6)||type==42))?5:4);}if(group>11)return s;if(ancient)effective=a.baseLevel+30;
 unsigned chaos=item.index==2*512+6?15:item.index==5*512+7?25:item.index==4*512+6?30:0;
 auto attack=[&](unsigned base,unsigned divisor,unsigned bonus){if(!base)return 0u;unsigned value=base;if(ancient&&a.baseLevel)value+=a.damageMin*25/a.baseLevel+5+effective/divisor+bonus;else if(item.excellent)value+=chaos?chaos:a.baseLevel?a.damageMin*25/a.baseLevel+5:0;return value+upgrade;};
 s.damageMin=attack(a.damageMin,40,5);s.damageMax=attack(a.damageMax,40,5);
 s.blocking=a.blocking;if(s.blocking){if(a.baseLevel&&(item.excellent||ancient))s.blocking+=a.blocking*25/a.baseLevel+5+(ancient?effective/40+5:0);s.blocking+=upgrade;}
 s.defense=a.defense;if(s.defense){if(group==6){s.defense+=level;if(ancient&&effective)s.defense+=s.defense*20/effective+2;}else{if(a.baseLevel&&(item.excellent||ancient)){s.defense+=a.defense*12/a.baseLevel+a.baseLevel/5+4;if(ancient&&effective)s.defense+=s.defense*3/effective+effective/30+2;}s.defense+=upgrade;}}
 s.magicDefense=a.magicDefense?a.magicDefense+upgrade:0;
 // Client displays magic power as a percentage; source ZzzInventory::CalculateItem.
 if(a.magicPower){unsigned power=a.magicPower;if(a.baseLevel&&(item.excellent||ancient))power+=a.magicPower*25/a.baseLevel+5+(ancient?effective/60+2:0);power+=upgrade;s.magicPower=power/2+((group==2&&type>=8&&type<=15)?0:level*2);}
 // Item.cpp option requirement penalty (weapon/armor/shield groups).
 if(item.option&&group<=11&&s.requirements[0])s.requirements[0]+=item.option*4;
 return s;}
}
